"""
        Converts degree to radian
        input: angle in degree
        output: angle in radian
        """
def ConvertToRadian(degree: Any) -> object {
    degree = float(degree);
    pi = 22 / 7;
    radian = float((degree * (pi / 180)));
    return radian;
}

